/// Emitted when editing a queued prompt is over: saved, with what it now
/// holds, or cancelled.
pub enum QueuedEdit {
    Saved {
        text: String,
        mode: SendMode,
        attached_text: Vec<String>,
        /// The images attached to it, not yet saved.
        attached_images: Vec<AttachedImage>,
    },
