                    if let Ok(saved) = &saved {
                        prompt_queue::remove(&saved.file).ok();
                    }
                    return;
                };
                match saved {
                    Ok(saved) => {
                        item.saved = Some(saved);
                        if let Some(ix) = this.queue.iter().position(|item| item.id == id) {
                            this.keep_new_conversation(ix);
                        }
                    }
                    Err((old, err)) => {
                        item.text = old_text;
